Let me design index.js similar to setprototypeof package:

```js
'use strict';

module.exports = Object.setPrototypeOf || ({ __proto__: [] } instanceof Array ? setProtoOf : mixinProperties);

function setProtoOf(obj, proto) {
  obj.__proto__ = proto;
  return obj;
}

function mixinProperties(obj, proto) {
  for (var prop in proto) {
    if (!Object.prototype.hasOwnProperty.call(obj, prop)) {
      obj[prop] = proto[prop];
    }
  }
  return obj;
}
```

Note: `mixinProperties` doesn't truly set prototype, but is the fallback for engines lacking both. That's the known implementation.

