'use strict';

module.exports = setPrototypeOf;

/**
 * Set the prototype (i.e. the internal [[Prototype]]) of `obj` to `proto`.
 *
 * Uses the fastest mechanism available in the current runtime:
 *  1. `Object.setPrototypeOf` (ES2015)
 *  2. the `__proto__` accessor (widely implemented, including old browsers)
 *  3. a property-copying fallback for engines that support neither
 *
 * @param {Object} obj the object whose prototype will be set
 * @param {Object|null} proto the new prototype
 * @returns {Object} the same `obj`, now with its prototype set
 */
function setPrototypeOf(obj, proto) {
  if (typeof Object.setPrototypeOf === 'function') {
    return Object.setPrototypeOf(obj, proto);
  }

  if (supportsProto()) {
    obj.__proto__ = proto; // eslint-disable-line no-proto
    return obj;
  }

  return mixinProperties(obj, proto);
}

/**
 * Feature-detect the `__proto__` accessor. An array literal with a
 * `__proto__` member only keeps that member when `__proto__` is a real
 * setter rather than a plain own property.
 *
 * @returns {boolean}
 */
function supportsProto() {
  return (
    ' __proto__' in {} === false &&
    { __proto__: [] } instanceof Array
  );
}

/**
 * Last-resort fallback. It cannot retarget the prototype chain, so it copies
 * the inherited enumerable members onto the target instead. This gives code
 * that only relies on inherited properties a usable result on ancient engines.
 *
 * @param {Object} obj
 * @param {Object|null} proto
 * @returns {Object}
 */
function mixinProperties(obj, proto) {
  if (proto != null) {
    for (var key in proto) {
      if (!Object.prototype.hasOwnProperty.call(obj, key)) {
        obj[key] = proto[key];
      }
    }
  }

  return obj;
}

